INSERT INTO seed_questions (lesson_title, sort_order, question_text, answer_text) VALUES
    ('JDK JRE и JVM', 1, 'Чем отличается JDK от JRE и когда достаточно только JRE?',
     'JDK включает JRE плюс инструменты разработки (компилятор javac, отладчик и т.д.). JRE содержит только JVM и библиотеки для запуска программ. Если вы лишь запускаете готовое приложение, а не разрабатываете, достаточно JRE. Для написания и компиляции кода нужен JDK.'),
    ('JDK JRE и JVM', 2, 'За счёт чего обеспечивается принцип "write once, run anywhere"?',
     'Исходный код компилируется не в машинный код конкретной ОС, а в универсальный байткод. Этот байткод одинаков для всех платформ, а исполняется он конкретной реализацией JVM под данную ОС и архитектуру. Разной является только JVM, а байткод переносим.'),
    ('JDK JRE и JVM', 3, 'Что входит в JVM с точки зрения выполняемых задач?',
     'Загрузка и верификация классов, исполнение байткода (интерпретация и JIT-компиляция), управление памятью и сборка мусора.'),
    ('JDK JRE и JVM', 4, 'JVM - это программа или спецификация?',
     'JVM - это в первую очередь спецификация, у которой есть разные реализации: HotSpot, Eclipse OpenJ9, GraalVM и другие. Когда мы "устанавливаем JVM", мы фактически ставим одну из её реализаций.'),
    ('JDK JRE и JVM', 5, 'Почему начиная с Java 11 обычно устанавливают именно JDK, а не отдельный JRE?',
     'Oracle перестал поставлять отдельный JRE как самостоятельный продукт. Теперь ставят полный JDK, а минимальную среду выполнения при необходимости собирают из модулей с помощью утилиты jlink.'),

    ('Байткод Java', 1, 'Что такое байткод Java и в каком файле он хранится?',
     'Байткод - это платформенно-независимое промежуточное представление программы, набор инструкций для JVM. Он получается из исходного кода компилятором javac и хранится в файлах с расширением .class (по одному на класс или интерфейс).'),
    ('Байткод Java', 2, 'Почему говорят, что JVM - стековая машина?',
     'Потому что большинство инструкций байткода работают со стеком операндов, а не с регистрами процессора. Операнды кладутся на стек, инструкция снимает их, выполняет операцию и кладёт результат обратно на стек.'),
    ('Байткод Java', 3, 'С какого магического числа начинается файл .class?',
     'С магического числа 0xCAFEBABE. Оно позволяет JVM убедиться, что перед ней действительно файл класса Java в ожидаемом формате.'),
    ('Байткод Java', 4, 'Что означают префиксы i, l, f, d, a в названиях инструкций?',
     'Они указывают тип операнда: i - int, l - long, f - float, d - double, a - ссылка (reference). Например, iadd складывает int, а aload загружает ссылку.'),
    ('Байткод Java', 5, 'Какая инструкция лежит в основе реализации лямбда-выражений и почему это удобно?',
     'invokedynamic. Лямбды не компилируются в анонимные классы заранее, а связываются во время выполнения через bootstrap-метод. Это уменьшает количество генерируемых классов и даёт гибкость реализации.'),
    ('Байткод Java', 6, 'Какой командой можно посмотреть байткод скомпилированного класса?',
     'Утилитой javap из состава JDK, например javap -c ИмяКласса выводит дизассемблированный байткод методов класса.'),

    ('AOT и JIT компиляция', 1, 'В чём главное отличие AOT от JIT компиляции?',
     'Момент компиляции. AOT компилирует байткод в машинный код заранее, до запуска программы. JIT компилирует во время выполнения, ориентируясь на профиль работающей программы.'),
    ('AOT и JIT компиляция', 2, 'Почему JIT способен давать более высокую пиковую производительность, чем AOT?',
     'JIT собирает профиль реального выполнения (какие методы горячие, какие типы встречаются, какие ветви берутся) и применяет оптимизации под конкретный сценарий: инлайнинг, устранение мёртвого кода, escape-анализ. AOT такого профиля не имеет.'),
    ('AOT и JIT компиляция', 3, 'Что такое warm-up (прогрев) и к какому подходу он относится?',
     'Warm-up - это период в начале работы JIT-подхода, когда код ещё интерпретируется или скомпилирован не полностью, поэтому работает медленнее. После компиляции горячих методов производительность выходит на пик. У AOT прогрева нет.'),
    ('AOT и JIT компиляция', 4, 'Что такое деоптимизация в контексте JIT?',
     'Это откат от скомпилированного машинного кода обратно к интерпретации, когда предположение, на котором строилась оптимизация (например, о типе объекта), оказалось неверным. Это позволяет JIT делать агрессивные, но безопасные оптимизации.'),
    ('AOT и JIT компиляция', 5, 'Какой инструмент чаще всего используют для AOT-компиляции Java и где это выгодно?',
     'GraalVM Native Image, компилирующий приложение в самостоятельный нативный образ. Это выгодно там, где важен быстрый старт и низкое потребление памяти: serverless-функции, CLI-утилиты, контейнеры.'),
    ('AOT и JIT компиляция', 6, 'Что такое многоуровневая компиляция (tiered compilation) в HotSpot?',
     'Это сочетание компиляторов C1 и C2. C1 (client) быстро выдаёт умеренно оптимизированный код для раннего ускорения, а C2 (server) позднее компилирует горячие методы с максимальными оптимизациями. Так балансируются время старта и пиковая производительность.'),

    ('Загрузчики классов', 1, 'Какие три основных загрузчика классов есть в JVM и что они загружают?',
     'Bootstrap ClassLoader загружает базовые классы платформы (java.base). Platform ClassLoader (ранее Extension) загружает классы платформенных модулей. Application (System) ClassLoader загружает классы приложения из classpath.'),
    ('Загрузчики классов', 2, 'В чём суть принципа делегирования родителю?',
     'Прежде чем загрузить класс самостоятельно, загрузчик передаёт запрос своему родителю вверх по иерархии. Только если ни один родитель не смог загрузить класс, загрузчик пытается сделать это сам. Это обеспечивает безопасность и отсутствие дублирования системных классов.'),
    ('Загрузчики классов', 3, 'Почему нельзя подменить системный класс вроде java.lang.String своим?',
     'Из-за делегирования родителю: запрос на загрузку java.lang.String дойдёт до bootstrap-загрузчика, который загрузит настоящий класс из java.base. Пользовательский класс с тем же именем просто не будет загружен.'),
    ('Загрузчики классов', 4, 'Чем идентифицируется класс в JVM и почему это важно?',
     'Парой "полное имя класса + загрузчик, который его загрузил". Один и тот же по имени класс, загруженный разными загрузчиками, считается разными типами. Это лежит в основе изоляции приложений и плагинов, но может приводить к ClassCastException между "одинаковыми" классами.'),
    ('Загрузчики классов', 5, 'Чем отличается ClassNotFoundException от NoClassDefFoundError?',
     'ClassNotFoundException - проверяемое исключение, возникает при попытке загрузить класс по имени во время выполнения (например, через Class.forName), когда класс не найден. NoClassDefFoundError - ошибка, возникает, когда класс был доступен при компиляции, но отсутствует во время выполнения.'),
    ('Загрузчики классов', 6, 'Какой загрузчик вернёт String.class.getClassLoader() и почему?',
     'Вернёт null. Класс String загружается bootstrap-загрузчиком, который написан на нативном коде и не представлен объектом Java, поэтому в API он обозначается как null.'),

    ('Рефлексия в Java', 1, 'Что такое рефлексия и на каком классе она основана?',
     'Рефлексия - это механизм исследования и изменения структуры программы во время выполнения: доступ к классам, полям, методам, конструкторам и аннотациям. Основная точка входа - объект java.lang.Class, дающий доступ к метаданным типа.'),
    ('Рефлексия в Java', 2, 'Какими способами можно получить объект Class?',
     'Тремя основными способами: через литерал Тип.class, через метод объекта getClass() и по имени во время выполнения через Class.forName("имя").'),
    ('Рефлексия в Java', 3, 'Как рефлексия позволяет обращаться к приватным полям и в чём опасность?',
     'С помощью метода setAccessible(true) на объекте Field или Method можно отключить проверку доступа и работать с приватными членами. Опасность в нарушении инкапсуляции, потере гарантий класса и возможных проблемах с системой модулей начиная с Java 9.'),
    ('Рефлексия в Java', 4, 'Почему рефлексия важна для фреймворков?',
     'Фреймворки (Spring, Hibernate, Jackson, JUnit) должны работать с пользовательскими классами, о которых ничего не знают на этапе компиляции. Рефлексия позволяет им во время выполнения создавать объекты, внедрять зависимости, читать аннотации, вызывать методы и работать с полями.'),
    ('Рефлексия в Java', 5, 'Какие есть недостатки у рефлексии?',
     'Она медленнее прямых вызовов, нарушает инкапсуляцию, не даёт проверок на этапе компиляции (ошибки в именах всплывают только в рантайме) и плохо поддаётся статическому анализу, что осложняет AOT-компиляцию.'),
    ('Рефлексия в Java', 6, 'Какое условие нужно, чтобы читать аннотацию через рефлексию во время выполнения?',
     'Аннотация должна иметь политику удержания RetentionPolicy.RUNTIME. Аннотации с политикой SOURCE или CLASS недоступны через рефлексию во время выполнения, так как не сохраняются в загруженном классе.'),

    ('Структура кучи и области памяти', 1, 'Какие области памяти в JVM разделяются между потоками, а какие принадлежат отдельному потоку?',
     'Разделяемые: куча (Heap) и Metaspace. Свои у каждого потока: JVM Stack (стек с кадрами методов), PC Register (счётчик команд) и Native Method Stack.'),
    ('Структура кучи и области памяти', 2, 'Где хранятся объекты, а где примитивные локальные переменные?',
     'Все объекты и массивы хранятся в куче. Примитивные локальные переменные хранятся в стеке потока. Для объекта в стеке лежит только ссылка, а сам объект - в куче.'),
    ('Структура кучи и области памяти', 3, 'Из каких областей состоит молодое поколение?',
     'Из Eden и двух областей Survivor (S0 и S1). Новые объекты создаются в Eden, а пережившие сборку перемещаются в Survivor.'),
    ('Структура кучи и области памяти', 4, 'Какая ошибка возникает при бесконечной рекурсии и почему?',
     'StackOverflowError. Каждый вызов метода добавляет в стек потока новый кадр (frame). Бесконечная рекурсия не даёт кадрам освобождаться, стек переполняется, и JVM бросает эту ошибку.'),
    ('Структура кучи и области памяти', 5, 'Чем OutOfMemoryError: Java heap space отличается от OutOfMemoryError: Metaspace?',
     'Первая означает переполнение кучи - не хватает памяти под объекты (мало heap или утечка). Вторая означает переполнение области метаданных классов - загружено слишком много классов (или их не выгружают).'),
    ('Структура кучи и области памяти', 6, 'На какой гипотезе основано деление кучи на поколения?',
     'На слабой гипотезе о поколениях: большинство объектов живут очень недолго. Поэтому кучу делят на молодое и старое поколения, чтобы часто и дёшево собирать короткоживущие объекты в молодом поколении.'),

    ('PermGen и Metaspace', 1, 'Что хранится в PermGen и Metaspace?',
     'Метаданные классов: описания структуры классов, сигнатуры методов, пул констант. Дополнительно в PermGen до Java 7 хранились String pool и статические переменные. Сами объекты хранятся не здесь, а в куче.'),
    ('PermGen и Metaspace', 2, 'В чём главное отличие Metaspace от PermGen?',
     'PermGen находился внутри кучи JVM и имел фиксированный размер. Metaspace располагается в нативной памяти ОС и по умолчанию растёт автоматически, ограничиваясь лишь доступной памятью (или флагом MaxMetaspaceSize).'),
    ('PermGen и Metaspace', 3, 'В какой версии Java исчез PermGen и что пришло ему на смену?',
     'PermGen был удалён в Java 8, его роль заняла область Metaspace, расположенная в нативной памяти.'),
    ('PermGen и Metaspace', 4, 'Почему ошибка OutOfMemoryError: PermGen space была частой проблемой?',
     'PermGen имел фиксированный, заранее заданный размер, который сложно предсказать. Приложения, динамически загружающие много классов (сервера приложений, фреймворки), исчерпывали его, особенно при перезагрузках без выгрузки классов.'),
    ('PermGen и Metaspace', 5, 'Куда в Java 7 переехал String pool и зачем?',
     'String pool переехал из PermGen в кучу. Это позволило сборщику мусора освобождать неиспользуемые строки и уменьшило давление на PermGen с его фиксированным размером.'),
    ('PermGen и Metaspace', 6, 'Может ли возникнуть OutOfMemoryError, связанный с Metaspace?',
     'Да. Если задан флаг MaxMetaspaceSize и загружено слишком много классов (или они не выгружаются), возникает OutOfMemoryError: Metaspace. Без ограничения Metaspace растёт, пока хватает нативной памяти.'),

    ('Виды ссылок в Java', 1, 'Чем отличается поведение SoftReference от WeakReference при сборке мусора?',
     'Объект с только мягкими ссылками собирается лишь при нехватке памяти (когда JVM близка к OutOfMemoryError). Объект с только слабыми ссылками собирается при ближайшей сборке мусора независимо от давления на память.'),
    ('Виды ссылок в Java', 2, 'Для чего лучше всего подходят мягкие ссылки?',
     'Для кэшей объектов, которые можно при необходимости пересоздать. Пока памяти достаточно, объекты кэша живут и ускоряют работу; при нехватке памяти GC их освобождает, предотвращая OutOfMemoryError.'),
    ('Виды ссылок в Java', 3, 'Что возвращает метод get() у PhantomReference и почему?',
     'Всегда null. Фантомная ссылка не предназначена для доступа к объекту, её цель - узнать, что объект уже готов к удалению, через попадание ссылки в ReferenceQueue, и выполнить очистку ресурсов.'),
    ('Виды ссылок в Java', 4, 'Как устроен и для чего полезен WeakHashMap?',
     'В WeakHashMap ключи удерживаются слабыми ссылками. Как только ключ становится недостижимым по сильным ссылкам, запись автоматически удаляется при сборке мусора. Это удобно для хранения метаданных, привязанных к объектам, без риска утечки.'),
    ('Виды ссылок в Java', 5, 'Зачем ссылки связывают с ReferenceQueue?',
     'Чтобы получать уведомления о том, что объект собран (или готов к удалению). Когда GC обрабатывает объект, связанная с ним ссылка помещается в очередь, и программа может отреагировать - например, освободить связанные ресурсы.'),
    ('Виды ссылок в Java', 6, 'Почему фантомные ссылки считают более безопасной альтернативой finalize()?',
     'finalize() выполняется в неопределённый момент, может воскресить объект и замедляет сборку. Фантомные ссылки с ReferenceQueue дают контролируемый и предсказуемый механизм очистки уже после того, как объект стал недостижим, без риска его воскрешения.'),

    ('Garbage Collector', 1, 'Какой объект считается мусором в Java?',
     'Объект, до которого нельзя добраться по цепочке ссылок ни от одного из GC roots (корней сборки мусора). Такой объект недостижим, и занятая им память может быть освобождена.'),
    ('Garbage Collector', 2, 'Почему подсчёта ссылок (reference counting) недостаточно для сборки мусора?',
     'Подсчёт ссылок не умеет собирать циклические ссылки: два объекта могут ссылаться друг на друга, имея ненулевой счётчик, но при этом быть недостижимыми от корней. Обход графа от GC roots решает эту проблему, так как ориентируется на достижимость, а не на счётчик.'),
    ('Garbage Collector', 3, 'Что относится к GC roots?',
     'Локальные переменные и параметры методов в стеках потоков, активные потоки, статические поля классов, ссылки из нативного кода (JNI).'),
    ('Garbage Collector', 4, 'Гарантирует ли вызов System.gc() немедленную сборку мусора?',
     'Нет. System.gc() - это лишь подсказка JVM. Виртуальная машина может её проигнорировать или отложить сборку. Полагаться на этот вызов в логике программы нельзя.'),
    ('Garbage Collector', 5, 'В чём суть гипотезы о поколениях и как она влияет на устройство GC?',
     'Слабая гипотеза о поколениях утверждает, что большинство объектов живут очень недолго. Поэтому кучу делят на поколения (молодое и старое), а молодое собирают чаще и дешевле, что повышает эффективность сборки.'),
    ('Garbage Collector', 6, 'Какой сборщик мусора используется по умолчанию в современных версиях Java?',
     'Начиная с Java 9 по умолчанию используется G1 GC, который делит кучу на регионы и балансирует между длиной пауз и пропускной способностью. Для больших куч с требованиями к малым паузам применяют ZGC или Shenandoah.'),

    ('Как работает сборка мусора', 1, 'Из каких фаз состоит алгоритм Mark and Sweep и какой у него недостаток?',
     'Фаза Mark помечает достижимые от корней объекты, фаза Sweep освобождает память непомеченных. Главный недостаток - фрагментация памяти: свободные участки чередуются с занятыми, из-за чего сложно выделять крупные объекты.'),
    ('Как работает сборка мусора', 2, 'Как алгоритм с уплотнением (Compact) решает проблему фрагментации?',
     'После пометки живые объекты сдвигаются в начало области, устраняя разрывы между ними. Свободная память становится непрерывной, и выделять новые объекты можно простым сдвигом указателя.'),
    ('Как работает сборка мусора', 3, 'Почему копирующий сборщик хорошо подходит для молодого поколения?',
     'Молодых объектов много, но живут они недолго, поэтому живых при сборке мало. Копирование только живых объектов в другую область выполняется быстро и не оставляет фрагментации. Плата - необходимость держать резервную область, но для короткоживущих объектов это оправдано.'),
    ('Как работает сборка мусора', 4, 'Чем Minor GC отличается от Full GC?',
     'Minor GC собирает только молодое поколение, происходит часто и вызывает короткие паузы. Full GC собирает всю кучу (молодое и старое поколения), происходит реже и обычно вызывает заметно более длительные паузы.'),
    ('Как работает сборка мусора', 5, 'Что означает продвижение (promotion) объекта?',
     'Это перемещение объекта из молодого поколения в старое. Оно происходит, когда объект пережил несколько сборок молодого поколения и его "возраст" превысил порог продвижения.'),
    ('Как работает сборка мусора', 6, 'Почему сборщик G1 называется Garbage First?',
     'G1 делит кучу на регионы и в первую очередь собирает те регионы, где больше всего мусора, получая максимальный эффект при заданном бюджете паузы. Отсюда и название - "мусор в первую очередь".'),

    ('Остановка мира Stop the World', 1, 'Что такое остановка мира (Stop the World)?',
     'Это пауза, во время которой JVM приостанавливает все потоки приложения, чтобы безопасно выполнить служебную работу, чаще всего сборку мусора. В это время полезный код приложения не выполняется.'),
    ('Остановка мира Stop the World', 2, 'Почему сборщику мусора вообще нужны STW-паузы?',
     'Сборщику нужно видеть согласованное состояние графа объектов. Если бы потоки приложения одновременно меняли ссылки и объекты перемещались, граф стал бы противоречивым. Поэтому как минимум некоторые фазы выполняются при остановленных потоках.'),
    ('Остановка мира Stop the World', 3, 'Что такое точки безопасности (safepoints)?',
     'Это места в коде, где состояние потока известно и согласовано, и потому его можно безопасно остановить. JVM не останавливает поток в произвольный момент, а ждёт, пока он дойдёт до ближайшего safepoint.'),
    ('Остановка мира Stop the World', 4, 'Как современные сборщики (ZGC, Shenandoah) уменьшают паузы?',
     'Они выполняют почти всю работу (пометку и перемещение объектов) конкурентно, одновременно с работой приложения, используя специальные барьеры. Благодаря этому STW-паузы сокращаются до единиц миллисекунд даже на больших кучах.'),
    ('Остановка мира Stop the World', 5, 'Только ли сборка мусора вызывает STW-паузы?',
     'Нет. К STW-паузам также приводят деоптимизация JIT-кода, снятие смещённых блокировок, снятие дампов потоков и другие служебные операции JVM, требующие согласованного состояния.'),

    ('Утечки памяти в Java', 1, 'Что такое утечка памяти в Java и чем она отличается от утечки в C++?',
     'Это ситуация, когда ненужные объекты остаются достижимыми от GC roots, и сборщик не может их удалить. В C++ утечка - это потеря указателя на выделенную память, а в Java наоборот: причина утечки в лишних ссылках, которые удерживают объект.'),
    ('Утечки памяти в Java', 2, 'Почему статические коллекции - частый источник утечек?',
     'Статические поля достижимы всё время работы приложения (через класс они являются частью корней). Если в статическую коллекцию постоянно добавлять элементы и не удалять их, объекты остаются живыми навсегда, и память только растёт.'),
    ('Утечки памяти в Java', 3, 'Почему ThreadLocal опасен в пулах потоков?',
     'Значение ThreadLocal живёт, пока жив поток. В пуле потоки переиспользуются и не завершаются, поэтому забытые значения ThreadLocal накапливаются и не собираются. Нужно явно вызывать remove() после использования.'),
    ('Утечки памяти в Java', 4, 'Как некорректные equals/hashCode могут привести к утечке?',
     'Если ключ в HashMap имеет неправильные equals/hashCode или его изменили после вставки, запись становится недостижимой для операций поиска и удаления, но остаётся в структуре и продолжает занимать память.'),
    ('Утечки памяти в Java', 5, 'Какими инструментами обнаруживают утечки памяти?',
     'Снимают heap dump (jmap или флаг HeapDumpOnOutOfMemoryError) и анализируют его в Eclipse MAT или VisualVM, изучая dominator tree и retained set. Также помогают мониторинг графика кучи и профилирование через Java Flight Recorder.'),
    ('Утечки памяти в Java', 6, 'Как слабые ссылки помогают избежать утечек в кэшах?',
     'Слабые ссылки (например, через WeakHashMap) не мешают сборщику удалить объект, если на него нет сильных ссылок. Такой кэш автоматически освобождает записи под давлением памяти, что снижает риск неконтролируемого роста.'),

    ('Модель памяти Java JMM', 1, 'Какие три основные проблемы многопоточности решает JMM?',
     'Видимость (когда изменения одного потока становятся видны другим), переупорядочивание операций (компилятором, JIT и процессором) и атомарность (гарантии неделимости некоторых операций).'),
    ('Модель памяти Java JMM', 2, 'Что гарантирует ключевое слово volatile и чего оно не гарантирует?',
     'volatile гарантирует видимость (запись сразу видна другим потокам, чтение возвращает актуальное значение) и запрещает переупорядочивание вокруг обращения к полю. Оно не гарантирует атомарность составных операций, например count++ по-прежнему небезопасен.'),
    ('Модель памяти Java JMM', 3, 'Чем synchronized отличается от volatile по предоставляемым гарантиям?',
     'volatile даёт только видимость и запрет переупорядочивания для одного поля. synchronized дополнительно обеспечивает взаимное исключение (только один поток в критической секции) и видимость всех изменений, сделанных внутри блока, для следующего входящего потока.'),
    ('Модель памяти Java JMM', 4, 'Почему без синхронизации поток может "не увидеть" изменение переменной другим потоком?',
     'Значение может оставаться в кэше ядра процессора или в рабочей памяти потока и не попадать своевременно в основную память. Без volatile или synchronized нет гарантии, что другой поток прочитает свежее значение.'),
    ('Модель памяти Java JMM', 5, 'Какие гарантии даёт JMM для final-полей?',
     'Корректно инициализированные в конструкторе final-поля становятся видимыми другим потокам без дополнительной синхронизации сразу после завершения конструктора, при условии что ссылка на объект не была опубликована до окончания конструктора.'),

    ('Happens-before', 1, 'Что означает отношение happens-before между операциями A и B?',
     'Если A happens-before B, то все изменения памяти, сделанные до и во время A, гарантированно видны в B. Это гарантия видимости и упорядочивания, а не утверждение о физическом времени выполнения.'),
    ('Happens-before', 2, 'Какое правило happens-before связано с volatile?',
     'Запись в volatile-поле happens-before любого последующего чтения того же поля. Благодаря этому читатель, увидевший новое значение volatile-переменной, видит и все изменения, сделанные писателем до этой записи.'),
    ('Happens-before', 3, 'Как happens-before связано с synchronized?',
     'Выход из synchronized-блока (освобождение монитора) happens-before последующего входа в тот же монитор. Поэтому поток, вошедший в критическую секцию, видит все изменения, сделанные предыдущим потоком до выхода.'),
    ('Happens-before', 4, 'Что такое транзитивность happens-before и зачем она нужна?',
     'Если A happens-before B и B happens-before C, то A happens-before C. Транзитивность позволяет строить цепочки гарантий, например через volatile-флаг обеспечить видимость обычных (не volatile) переменных, записанных до него.'),
    ('Happens-before', 5, 'Что произойдёт, если между двумя обращениями к общим данным нет отношения happens-before?',
     'Возникает гонка данных (data race), если хотя бы одно обращение - запись. Поведение программы становится непредсказуемым: читатель может видеть устаревшее значение или не увидеть обновление вовсе.'),
    ('Happens-before', 6, 'Даёт ли Thread.start() какие-либо гарантии happens-before?',
     'Да. Вызов Thread.start() happens-before любой операции в запущенном потоке. Это значит, что новый поток видит все изменения, сделанные родительским потоком до вызова start().'),

    ('As-if-serial', 1, 'Что гарантирует принцип as-if-serial?',
     'Что результат выполнения однопоточной программы будет таким же, как если бы все инструкции выполнялись строго в порядке текста программы, несмотря на любые переупорядочивания компилятором, JIT и процессором.'),
    ('As-if-serial', 2, 'Какие операции нельзя переупорядочивать в рамках as-if-serial?',
     'Операции, между которыми есть зависимость по данным. Например, вычисление, использующее результат предыдущей операции, нельзя выполнить раньше неё. Независимые операции переставлять можно.'),
    ('As-if-serial', 3, 'Почему as-if-serial недостаточно для корректной многопоточной программы?',
     'Потому что эта гарантия действует только в пределах одного потока. Переупорядочивания, незаметные внутри потока, могут стать видимыми другим потокам. Для межпоточных гарантий нужен механизм happens-before (volatile, synchronized и т.д.).'),
    ('As-if-serial', 4, 'В примере с data и ready почему читатель может увидеть data = 0?',
     'Между записями data = 42 и ready = true нет зависимости по данным, поэтому компилятор или процессор могут их переставить. As-if-serial это разрешает, ведь для потока-писателя результат не меняется. Но другой поток может увидеть ready = true раньше, чем data = 42.'),
    ('As-if-serial', 5, 'Как связаны as-if-serial и happens-before?',
     'As-if-serial обеспечивает предсказуемость внутри одного потока, а happens-before распространяет гарантии видимости и порядка на взаимодействие между потоками. Вместе они описывают, как безопасно рассуждать о коде в одно- и многопоточной среде.');

DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM seed_questions q
        LEFT JOIN seed_lessons l ON l.title = q.lesson_title
        WHERE l.title IS NULL
    ) THEN
        RAISE EXCEPTION 'seed_questions references a lesson missing from seed_lessons';
    END IF;
    IF EXISTS (
        SELECT 1 FROM seed_lessons l
        LEFT JOIN seed_questions q ON q.lesson_title = l.title
        WHERE q.lesson_title IS NULL
    ) THEN
        RAISE EXCEPTION 'seed_lessons contains a lesson without questions';
    END IF;
END $$;

INSERT INTO lessons (topic_id, title, active, sort_order)
SELECT t.id, s.title, TRUE, s.sort_order
FROM seed_lessons s
JOIN topics t ON t.title = 'Особенности внутренней работы Java'
JOIN courses c ON c.id = t.course_id AND c.slug = 'java-core';

INSERT INTO questions (lesson_id, question_text, answer_text, active, sort_order)
SELECT l.id, q.question_text, q.answer_text, TRUE, q.sort_order
FROM seed_questions q
JOIN lessons l ON l.title = q.lesson_title
JOIN topics t ON t.id = l.topic_id AND t.title = 'Особенности внутренней работы Java'
JOIN courses c ON c.id = t.course_id AND c.slug = 'java-core';
